// DeriveCTAURLFields: fields ending "_url" with a sibling "<stem>_label" or
// "<stem>_text". Sibling test is load-bearing: 32 site_assets image/logo
// fields also end in _url and must never be touched. Sorted output.
func DeriveCTAURLFields(inputSchema map[string]interface{}) []CTAField { ... }

// UncoveredCTAURLFields: fields ending "_url" whose source is query-resolved
// (site_specs./pages./config. — site_assets. excluded) with NO sibling label.
// Warn-only THIS ROUND; the flip round must replace this with a consumed
// detection path (named handler) or the flip does not ship — see risks.
func UncoveredCTAURLFields(inputSchema map[string]interface{}) []string { ... }

+ // sectionInputSchema extracts the component's input_schema from a
+ // sections_ready entry. plan_sections attaches Component: comp.Raw, where
+ // input_schema is a JSON string (DB round-trip) or a map (in-process).
+ func sectionInputSchema(section map[string]interface{}) map[string]interface{} {
+   comp, _ := section["component"].(map[string]interface{})
+   if comp == nil { return nil }
+   switch s := comp["input_schema"].(type) {
+   case map[string]interface{}: return s
+   case string:
+     var m map[string]interface{}
+     if json.Unmarshal([]byte(s), &m) == nil { return m }
+   }
+   return nil
+ }

  fields, isCTA := ctaFieldNames[function]
+ if schema := sectionInputSchema(section); schema != nil {
+   if d := ctaDerivationDelta(function, fields, isCTA, datahelpers.DeriveCTAURLFields(schema)); d != "" {
+     logger.Info("resolve_internal_links: cta derivation delta (observe-only)", zap.String("component", function), zap.String("delta", d))
+   }
+   for _, f := range datahelpers.UncoveredCTAURLFields(schema) {
+     logger.Warn("resolve_internal_links: uncovered cta url field", zap.String("component", function), zap.String("field", f))
+   }
+ }
  if !isCTA { continue }

// per-field loop, query-resolved branch, AFTER value resolves:
+ if ctaOwned[fieldName] {   // built once per section from DeriveCTAURLFields
+   if prev, ok := resolvedData[fieldName]; ok && prev != value {
+     logger.Info("plan_sections: cta ownership conflict (observe-only)",
+       zap.String("field", fieldName), zap.String("source", source))
+   }
+ }
  resolvedData[fieldName] = value   // UNCHANGED this round
// Flip design (deferred, binding constraints in risks): skip re-resolution for
// resolver-owned fields; a required field with no fallback follows the
// schema's own on_missing — never a bare continue.
